AI=float(np.sqrt(.68))
PAIRS=[dict(name='direct_vs_noisy_indirect',models=[('direct',p(c=.4,alpha=AI/np.sqrt(2),beta1=.8,beta=0.,qy=.5)),('indirect',p(c=.4,alpha=AI,beta=.8,qy=.25))],prior_allowed=[False,True],prior='independent calibration qY=.25 and Z->X coefficient beta=.8; fixed before labels',weak_prior='qY=.25 alone also admits a gain-rescaled direct alternative'),dict(name='positive_mixed_cancellation',models=[('mixed',p(a=.3,c=.8,alpha=.5,beta1=.5,beta=.5,qz=0.)),('direct',p(a=.8,c=.8,alpha=.5,beta1=.5,beta=0.,qz=0.))],prior_allowed=[False,True],prior='minimal transfer realization: no exact source pole cancellation; an external structural assumption'),dict(name='source_middle_clock_swap',models=[('indirect_clock_A',p(a=.8,c=.4,alpha=.5,beta=.8,qz=0.)),('indirect_clock_B',p(a=.4,c=.8,alpha=.5,beta=.8,qz=0.))],prior_allowed=[True,False],prior='independent role calibration source persistence a >= .7')]
INFOS=['C0_X','C1_XZ','C2_Y','C2_Z','C2_X_negative','C3_constraints_X']
PROTOCOL=dict(name='L3-C additional information and finite-candidate identifiability',scope='only L3-C, not L3-D learned classifier or L4 warning',seeds=SEEDS,n_test_per_truth_seed_noise=N,T=T,prefixes=PREFIXES,measurement_noise_std=NOISE,process='three-state linear Gaussian, all candidates contain a physical Z channel; direct means no Z->X target path',stationary_initial=True,primary=PRIMARY,equivalent_pairs=PAIRS,information=INFOS,input=dict(amplitude=.5,start=50,stop=450,half_period=16,schedule='fixed alternating square wave, known target, unit additive gain to selected state equation',prediction='S[t+1]=A S[t]+e_target*u[t]+epsilon[t]'),comparison='exact known-candidate Gaussian likelihood reference; no parameter learning or hidden-state answers supplied per trajectory',candidate_prior='equal among admissible candidates; physical constraints predeclared; invalid-prior tests retain actual excluded truths',declaration='maximum finite-candidate posterior >= .95, otherwise refuse; posterior conditional on full candidate specification, not universal calibrated causal confidence',C3_primary='shared true bounds all three candidates satisfy; no pruning and no extra benefit manufactured',C3_weak='matched direct scaled to qY=.25 beta1=.8 sqrt2 remains equal to indirect under X; calibrated qY alone cannot break ambiguity',paired='same process/measurement innovations across input/noise information conditions within each pool/truth/seed; C0 and C1 share X observations',main_questions=['do added joint covariances differ?','do targeted controlled means differ?','does prior remove true or false candidates?','what remains indistinguishable?'],metrics=['correct declaration','wrong declaration','refusal','forced accuracy diagnostic','posterior','prior validity','law difference','controlled response difference'],statistics='trajectory sampling within seed; compare paired trajectories, do not treat timepoints or prefixes as independent',not_claimed=['unknown-parameter causal discovery','automatic universal nonidentifiability detection','real physical calibration','early warning'])
